function renderMapLegend(key){$('mapLegend').innerHTML=(DATA.regions[key]?.silentPresence||DATA.regions[key]?.cordon)?Object.entries(TIER_NAMES).map(([tier,name])=>`<span style="--c:${TIER_COLORS[tier]}">T${tier} ${name}</span>`).join(''):key==='frontier'?'<span style="--c:#7bbba0">Elysian Collective</span><span style="--c:#dfbd78">Prathia / Kadaym</span><span style="--c:#93abc9">Independent</span><span style="--c:#e57d82">Silent hazard</span>':'<span style="--c:#dfbd78">Federation</span><span style="--c:#7bbba0">Collective</span><span style="--c:#93abc9">Neighbor / neutral</span><span style="--c:#e57d82">Hazard / unresolved</span>'}
